source_texts.stable_word_deduplication:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    seen = set()
    retained = []
    for word in lines[1:n + 1]:
        if word not in seen:
            seen.add(word)
            retained.append(word)
    print("|".join(retained))


if __name__ == "__main__":
    main()

source_texts.longest_rising_run:
import sys


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    if n == 0:
        print(0)
        return

    values = [int(value) for value in lines[1:n + 1]]
    longest = 1
    current = 1
    for previous, value in zip(values, values[1:]):
        if value > previous:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
    print(longest)


if __name__ == "__main__":
    main()

