source_texts.stable_word_deduplication:
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();

    for word in lines.take(n) {
        if seen.insert(word.to_owned()) {
            retained.push(word);
        }
    }

    println!("{}", retained.join("|"));
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for i in k..n {
        sum += numbers[i] - numbers[i - k];
        sums.push(sum.to_string());
    }

    println!("{}", sums.join(","));
}

source_texts.longest_rising_run:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap_or("0").parse().unwrap();
    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;
    for value in values.take(n - 1) {
        let value: i128 = value.parse().unwrap();
        if value > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = value;
    }
    println!("{longest}");
}

source_texts.plurality_winner:
use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    for name in lines.take(n) {
        *counts.entry(name).or_default() += 1;
    }

    if let Some((name, count)) = counts.iter().max_by(|a, b| {
        a.1.cmp(b.1).then_with(|| b.0.cmp(a.0))
    }) {
        println!("{name} {count}");
    }
}

source_texts.longest_common_prefix:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap_or("");
    let mut prefix_len = first.len();
    for line in lines.take(n - 1) {
        prefix_len = first.as_bytes()[..prefix_len]
            .iter()
            .zip(line.as_bytes())
            .take_while(|(a, b)| a == b)
            .count();
    }
    println!("{}", &first[..prefix_len]);
}

