    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap_or("");
    let mut prefix_len = first.len();
    for line in lines.take(n - 1) {
        prefix_len = first.as_bytes()[..prefix_len]
