import sys


def main() -> None:
    lines = sys.stdin.buffer
    n = int(lines.readline())
    if n == 0:
        print(0)
        return

    previous = int(lines.readline())
    current = 1
    longest = 1
    for _ in range(n - 1):
        value = int(lines.readline())
        if value > previous:
            current += 1
            if current > longest:
                longest = current
        else:
            current = 1
        previous = value

    print(longest)


if __name__ == "__main__":
    main()

source_texts.plurality_winner:
import sys


def main() -> None:
    lines = sys.stdin.buffer
    n = int(lines.readline())
    if n == 0:
        return

    counts = {}
    for _ in range(n):
        name = lines.readline().decode().rstrip("\r\n")
        counts[name] = counts.get(name, 0) + 1

    winner = min(counts, key=lambda name: (-counts[name], name))
    print(winner, counts[winner])


if __name__ == "__main__":
    main()

