import sys


def main() -> None:
    text = sys.stdin.buffer.readline().decode().rstrip("\r\n")
    if not text:
        print()
        return

    groups = []
    current = text[0]
    count = 1
    for letter in text[1:]:
        if letter == current:
            count += 1
        else:
            groups.append(f"{current}:{count}")
            current = letter
            count = 1
    groups.append(f"{current}:{count}")

    print(",".join(groups))


if __name__ == "__main__":
    main()

source_texts.merge_sorted_intervals:
import sys


def main() -> None:
    lines = sys.stdin.buffer
    n = int(lines.readline())
    if n == 0:
        print()
        return

    current_start, current_end = map(int, lines.readline().split())
    merged = []
    for _ in range(n - 1):
        start, end = map(int, lines.readline().split())
        if start <= current_end:
            current_end = max(current_end, end)
        else:
            merged.append(f"{current_start}:{current_end}")
            current_start, current_end = start, end
    merged.append(f"{current_start}:{current_end}")

    print(",".join(merged))


if __name__ == "__main__":
    main()

