source_texts.longest_rising_run:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i64 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;
    for _ in 1..n {
        let value: i64 = values.next().unwrap().parse().unwrap();
        if value > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = value;
    }
    println!("{longest}");
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let k: usize = tokens.next().unwrap().parse().unwrap();
    let numbers: Vec<i64> = (0..n)
        .map(|_| tokens.next().unwrap().parse().unwrap())
        .collect();

    let mut sum: i64 = numbers[..k].iter().sum();
    let mut output = vec![sum.to_string()];
    for i in k..n {
        sum += numbers[i] - numbers[i - k];
        output.push(sum.to_string());
    }
    println!("{}", output.join(","));
}

source_texts.stable_word_deduplication:
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();

    for _ in 0..n {
        let word = tokens.next().unwrap();
        if seen.insert(word) {
            retained.push(word);
        }
    }
    println!("{}", retained.join("|"));
}

