import sys


def main():
    stream = sys.stdin
    n = int(stream.readline())
    words = [stream.readline().rstrip("\n") for _ in range(n)]
    if not words:
        print()
        return

    prefix = words[0]
    for word in words[1:]:
        limit = min(len(prefix), len(word))
        index = 0
        while index < limit and prefix[index] == word[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break
    print(prefix)


if __name__ == "__main__":
    main()

