use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().trim().parse().unwrap();
    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap().as_bytes().to_vec();
    let mut prefix_len = first.len();
    for line in lines.take(n - 1) {
        let bytes = line.as_bytes();
        prefix_len = (0..prefix_len.min(bytes.len()))
            .take_while(|&i| first[i] == bytes[i])
            .count();
    }
    println!("{}", std::str::from_utf8(&first[..prefix_len]).unwrap());
}

