sources.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.lines();
    let n: usize = values.next().unwrap().trim().parse().unwrap();
    let k: usize = values.next().unwrap().trim().parse().unwrap();
    let numbers: Vec<i128> = values
        .take(n)
        .map(|line| line.trim().parse().unwrap())
        .collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for i in k..n {
        sum += numbers[i] - numbers[i - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

