import sys


def main():
    lines = sys.stdin.buffer.readlines()
    n = int(lines[0])
    if n == 0:
        print()
        return

    texts = [line.rstrip(b"\r\n") for line in lines[1:1 + n]]
    prefix = texts[0]
    for text in texts[1:]:
        limit = min(len(prefix), len(text))
        index = 0
        while index < limit and prefix[index] == text[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break

    sys.stdout.buffer.write(prefix + b"\n")


if __name__ == "__main__":
    main()

