import sys


def main():
    lines = sys.stdin.buffer.readlines()
    n = int(lines[0])
    if n == 0:
        return

    counts = {}
    for raw_name in lines[1:1 + n]:
        name = raw_name.rstrip(b"\r\n").decode("ascii")
        counts[name] = counts.get(name, 0) + 1

    winner = min(counts, key=lambda name: (-counts[name], name))
    print(winner, counts[winner])


if __name__ == "__main__":
    main()

