    for line in lines.take(n - 1) {
        let line = line.unwrap();
        prefix_len = first
            .as_bytes()
            .iter()
            .zip(line.as_bytes())
            .take(prefix_len)
            .take_while(|(left, right)| left == right)
            .count();
    }
    println!("{}", &first[..prefix_len]);
}

