use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current_run = 1usize;
    let mut longest_run = 1usize;
    for value in values.take(n - 1) {
        let value: i128 = value.parse().unwrap();
        if value > previous {
            current_run += 1;
            longest_run = longest_run.max(current_run);
        } else {
            current_run = 1;
        }
        previous = value;
    }
    println!("{longest_run}");
}

sources.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let mut merged: Vec<(i128, i128)> = Vec::new();

    for _ in 0..n {
        let start: i128 = values.next().unwrap().parse().unwrap();
        let end: i128 = values.next().unwrap().parse().unwrap();
        if let Some(current) = merged.last_mut() {
            if start <= current.1 {
                current.1 = current.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }

    let output: Vec<String> = merged
        .into_iter()
        .map(|(start, end)| format!("{start}:{end}"))
        .collect();
    println!("{}", output.join(","));
}

sources.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
    for index in k..n {
        sum += numbers[index] - numbers[index - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

sources.plurality_winner:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    if n == 0 {
        return;
    }

    let mut counts: HashMap<&str, usize> = HashMap::new();
    for name in values.take(n) {
        *counts.entry(name).or_default() += 1;
    }
    let (winner, count) = counts
        .into_iter()
        .max_by(|(name_a, count_a), (name_b, count_b)| {
            count_a.cmp(count_b).then_with(|| name_b.cmp(name_a))
        })
        .unwrap();
    println!("{winner} {count}");
}

