source_texts.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap_or("0").parse().unwrap();
    let mut merged: Vec<(i128, i128)> = Vec::new();

    for _ in 0..n {
        let start: i128 = tokens.next().unwrap().parse().unwrap();
        let end: i128 = tokens.next().unwrap().parse().unwrap();
        if let Some(last) = merged.last_mut() {
            if start <= last.1 {
                last.1 = last.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }

    let output: Vec<String> = merged
        .into_iter()
        .map(|(start, end)| format!("{start}:{end}"))
        .collect();
    println!("{}", output.join(","));
}

