to main:
    let count_input be ask for a number ""
    let count be value of count_input
    if count is 0:
        say ""
    otherwise:
        let first be ask ""
        let prefix_letters be first split by ""
        let prefix_length be length of prefix_letters
        if count is more than 1:
            repeat (count - 1) times:
                let line be ask ""
                let letters be line split by ""
                let limit be prefix_length
                if length of letters is less than limit:
                    set limit to length of letters
                let matching be 0
                if limit is more than 0:
                    for each i from 1 to limit:
                        if (item i of prefix_letters) is (item i of letters):
                            if matching is i - 1:
                                set matching to i
                set prefix_length to matching
        let result be an empty list of text
        if prefix_length is more than 0:
            for each i from 1 to prefix_length:
                add item i of prefix_letters to result
        say result joined with ""

