import sys


n = int(sys.stdin.readline())
merged = []

for _ in range(n):
    start, end = map(int, sys.stdin.readline().split())
    if merged and start <= merged[-1][1]:
        merged[-1][1] = max(merged[-1][1], end)
    else:
        merged.append([start, end])

print(",".join(f"{start}:{end}" for start, end in merged))

