lines = [sys.stdin.readline().rstrip("\n") for _ in range(n)]

if not lines:
    print()
else:
    prefix = lines[0]
    for line in lines[1:]:
        while not line.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                break
        if not prefix:
            break
    print(prefix)

