use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut counts = BTreeMap::new();

    for name in lines.take(n) {
        *counts.entry(name).or_insert(0usize) += 1;
    }
    if let Some((name, count)) = counts.into_iter().max_by(|a, b| {
        a.1.cmp(&b.1).then_with(|| b.0.cmp(a.0))
    }) {
        println!("{} {}", name, count);
    }
}

source_texts.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap_or("0").parse().unwrap();
    let mut merged: Vec<(i64, i64)> = Vec::new();

    for _ in 0..n {
        let start: i64 = values.next().unwrap().parse().unwrap();
        let end: i64 = values.next().unwrap().parse().unwrap();
        if let Some(last) = merged.last_mut() {
            if start <= last.1 {
                last.1 = last.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }

    let output: Vec<String> = merged
        .into_iter()
        .map(|(start, end)| format!("{}:{}", start, end))
        .collect();
    println!("{}", output.join(","));
}

