source_texts.stable_word_deduplication:
import sys


def main() -> None:
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    seen = set()
    retained = []
    for word in lines[1 : n + 1]:
        if word not in seen:
            seen.add(word)
            retained.append(word)
    print("|".join(retained))


if __name__ == "__main__":
    main()

