import sys


def main() -> None:
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    if n == 0:
        return

    counts = {}
    for name in lines[1 : n + 1]:
        counts[name] = counts.get(name, 0) + 1

    winner = min(counts, key=lambda name: (-counts[name], name))
    print(winner, counts[winner])


if __name__ == "__main__":
    main()

source_texts.longest_rising_run:
import sys


def main() -> None:
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])
    if n == 0:
        print(0)
        return

    values = [int(value) for value in lines[1 : n + 1]]
    longest = 1
    current = 1
    for previous, value in zip(values, values[1:]):
        if value > previous:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
    print(longest)


if __name__ == "__main__":
    main()

