use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap_or("0").parse().unwrap();

    if n == 0 {
        println!("0");
        return;
    }

    let mut previous: i128 = values.next().unwrap().parse().unwrap();
    let mut current = 1usize;
    let mut longest = 1usize;
    for _ in 1..n {
        let value: i128 = values.next().unwrap().parse().unwrap();
        if value > previous {
            current += 1;
            longest = longest.max(current);
        } else {
            current = 1;
        }
        previous = value;
    }
    println!("{}", longest);
}

source_texts.longest_common_prefix:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let first = lines.next().unwrap_or("");
    let mut prefix_len = first.len();
    for line in lines.take(n - 1) {
        prefix_len = first
            .as_bytes()
            .iter()
            .zip(line.as_bytes())
            .take(prefix_len)
            .take_while(|(a, b)| a == b)
            .count();
    }
    println!("{}", &first[..prefix_len]);
}

source_texts.run_length_encoding:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut chars = line.chars();
    let Some(mut current) = chars.next() else {
        println!();
        return;
    };

    let mut count = 1usize;
    let mut groups = Vec::new();
    for ch in chars {
        if ch == current {
            count += 1;
        } else {
            groups.push(format!("{}:{}", current, count));
            current = ch;
            count = 1;
        }
    }
    groups.push(format!("{}:{}", current, count));
    println!("{}", groups.join(","));
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let k: usize = parts.next().unwrap().parse().unwrap();
    let values: Vec<i128> = parts.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut sums = vec![sum.to_string()];
    for i in k..n {
        sum += values[i] - values[i - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

