source_texts.longest_common_prefix:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut prefix = lines.next().unwrap_or("").to_string();
    for line in lines.take(n - 1) {
        let common = prefix
            .bytes()
            .zip(line.bytes())
            .take_while(|(a, b)| a == b)
            .count();
        prefix.truncate(common);
    }
    println!("{prefix}");
}

