use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap_or("0").parse().unwrap();
    if n == 0 {
        println!();
        return;
    }

    let mut start: i64 = values.next().unwrap().parse().unwrap();
    let mut end: i64 = values.next().unwrap().parse().unwrap();
    let mut merged = Vec::new();
    for _ in 1..n {
        let next_start: i64 = values.next().unwrap().parse().unwrap();
        let next_end: i64 = values.next().unwrap().parse().unwrap();
        if next_start <= end {
            end = end.max(next_end);
        } else {
            merged.push(format!("{start}:{end}"));
            start = next_start;
            end = next_end;
        }
    }
    merged.push(format!("{start}:{end}"));
    println!("{}", merged.join(","));
}

