use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut chars = line.chars();
    let Some(mut current) = chars.next() else {
        println!();
        return;
    };

    let mut count = 1usize;
    let mut groups = Vec::new();
    for ch in chars {
        if ch == current {
            count += 1;
        } else {
            groups.push(format!("{current}:{count}"));
            current = ch;
            count = 1;
        }
    }
    groups.push(format!("{current}:{count}"));
    println!("{}", groups.join(","));
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut sums = vec![sum.to_string()];
    for index in k..n {
        sum += numbers[index] - numbers[index - k];
        sums.push(sum.to_string());
    }
    println!("{}", sums.join(","));
}

