to main:
    let count_input be ask for a number ""
    if count_input is nothing:
        say ""
    otherwise:
        let count be value of count_input
        if count is 0:
            say ""
        otherwise:
            let first_line be ask ""
            let prefix_letters be first_line split by ""
            let prefix_length be length of prefix_letters
            if count is more than 1:
                for each line_index from 2 to count:
                    let line be ask ""
                    let letters be line split by ""
                    if length of letters is less than prefix_length:
                        set prefix_length to length of letters
                    let matching_length be 0
                    if prefix_length is more than 0:
                        for each i from 1 to prefix_length:
                            if item i of prefix_letters is item i of letters:
                                if matching_length is i - 1:
                                    set matching_length to i
                    set prefix_length to matching_length
            let output be an empty list of text
            if prefix_length is more than 0:
                for each i from 1 to prefix_length:
                    add (item i of prefix_letters) to output
            say output joined with ""

