import sys


def main():
    lines = sys.stdin.buffer.read().splitlines()
    n = int(lines[0])
    if n == 0:
        print()
        return

    texts = lines[1:n + 1]
    prefix = texts[0]
    for text in texts[1:]:
        limit = min(len(prefix), len(text))
        index = 0
        while index < limit and prefix[index] == text[index]:
            index += 1
        prefix = prefix[:index]
        if not prefix:
            break

    sys.stdout.buffer.write(prefix + b"\n")


if __name__ == "__main__":
    main()

