use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut fields = input.split_whitespace();
    let n: usize = fields.next().unwrap().parse().unwrap();
    let mut seen = HashSet::new();
    let mut retained = Vec::new();

    for _ in 0..n {
        let word = fields.next().unwrap();
        if seen.insert(word) {
            retained.push(word);
        }
    }

    println!("{}", retained.join("|"));
}

source_texts.plurality_winner:
use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut fields = input.split_whitespace();
    let n: usize = fields.next().unwrap().parse().unwrap();
    let mut counts: HashMap<&str, usize> = HashMap::new();

    for _ in 0..n {
        let name = fields.next().unwrap();
        *counts.entry(name).or_insert(0) += 1;
    }

    if let Some((name, count)) = counts
        .into_iter()
        .max_by(|(name_a, count_a), (name_b, count_b)| {
            count_a.cmp(count_b).then_with(|| name_b.cmp(name_a))
        })
    {
        println!("{name} {count}");
    }
}

source_texts.run_length_encoding:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let line = input.lines().next().unwrap_or("");
    let mut chars = line.chars();
    let mut groups = Vec::new();

    if let Some(mut current) = chars.next() {
        let mut count = 1usize;
        for ch in chars {
            if ch == current {
                count += 1;
            } else {
                groups.push(format!("{current}:{count}"));
                current = ch;
                count = 1;
            }
        }
        groups.push(format!("{current}:{count}"));
    }

    println!("{}", groups.join(","));
}

