use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut fields = input.split_whitespace();
    let n: usize = fields.next().unwrap().parse().unwrap();
    let k: usize = fields.next().unwrap().parse().unwrap();
    let values: Vec<i128> = (0..n)
        .map(|_| fields.next().unwrap().parse().unwrap())
        .collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut sums = Vec::with_capacity(n - k + 1);
    sums.push(sum.to_string());
