n = int(sys.stdin.readline())

if n == 0:
    print(0)
else:
    previous = int(sys.stdin.readline())
    current_length = 1
    longest = 1

    for _ in range(n - 1):
        value = int(sys.stdin.readline())
        if value > previous:
            current_length += 1
        else:
            current_length = 1
        if current_length > longest:
            longest = current_length
        previous = value

    print(longest)

