use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let k: usize = lines.next().unwrap_or("0").parse().unwrap();
    let words: Vec<&str> = lines.take(n).collect();

    if n == 0 {
        println!();
        return;
    }

    let shift = k % n;
    let rotated: Vec<&str> = words[shift..]
        .iter()
        .chain(words[..shift].iter())
        .copied()
        .collect();
    println!("{}", rotated.join("|"));
}

source_texts.moving_window_sums:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap().parse().unwrap();
    let k: usize = tokens.next().unwrap().parse().unwrap();
    let values: Vec<i128> = tokens.take(n).map(|s| s.parse().unwrap()).collect();

    let mut sum: i128 = values[..k].iter().sum();
    let mut sums = vec![sum.to_string()];
    for i in k..n {
        sum += values[i] - values[i - k];
        sums.push(sum.to_string());
    }

    println!("{}", sums.join(","));
}

source_texts.merge_sorted_intervals:
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut tokens = input.split_whitespace();
    let n: usize = tokens.next().unwrap_or("0").parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let mut start: i128 = tokens.next().unwrap().parse().unwrap();
    let mut end: i128 = tokens.next().unwrap().parse().unwrap();
    let mut merged = Vec::new();

    for _ in 1..n {
        let next_start: i128 = tokens.next().unwrap().parse().unwrap();
        let next_end: i128 = tokens.next().unwrap().parse().unwrap();
        if next_start <= end {
            end = end.max(next_end);
        } else {
            merged.push(format!("{}:{}", start, end));
            start = next_start;
            end = next_end;
        }
    }
    merged.push(format!("{}:{}", start, end));

    println!("{}", merged.join(","));
}

